const results = await Promise.allSettled([
  tools.exec_command({cmd:"entire status","max_output_tokens":3500}),
  tools.exec_command({cmd:"rg --files --hidden -g 'SKILL.md' .agents /home/peterc/.agents/skills | rg '/search/SKILL.md$'","max_output_tokens":2000})
]); results.forEach((r,i)=>text({i,...r}));

const results = await Promise.allSettled([
  tools.exec_command({cmd:"entire search --help","max_output_tokens":4500}),
  tools.exec_command({cmd:"git status --short --branch","max_output_tokens":2000}),
  tools.exec_command({cmd:"git log -5 --format='%H %s%n%b' -- PLAN.md","max_output_tokens":5500}),
  tools.exec_command({cmd:"rg --files --hidden -g AGENTS.md -g PLAN.md -g README.md -g package.json -g '!node_modules' -g '!.git' -g '!dist'","max_output_tokens":3000})
]); results.forEach((r,i)=>text({i,...r}));

const results = await Promise.allSettled([
  tools.exec_command({cmd:"cat AGENTS.md PLAN.md package.json","max_output_tokens":14000}),
  tools.exec_command({cmd:"git diff --stat","max_output_tokens":3000}),
  tools.exec_command({cmd:"entire checkpoint explain --checkpoint 01M32P3W0X3D9XSG7V2HTDT7GQ --json --no-pager","max_output_tokens":6500,"yield_time_ms":10000})
]); results.forEach((r,i)=>text({i,...r}));

const results = await Promise.allSettled([
  tools.exec_command({cmd:"cat .agents/skills/review/SKILL.md","max_output_tokens":5500}),
  tools.exec_command({cmd:"git diff -- src/orchestration/loop.ts src/policy.ts src/types.ts src/agents/types.ts","max_output_tokens":10000}),
  tools.exec_command({cmd:"sed -n '1,280p' src/agents/context.ts","max_output_tokens":9500}),
  tools.exec_command({cmd:"entire checkpoint explain --help","max_output_tokens":3000})
]); results.forEach((r,i)=>text({i,...r}));

